class Fenwick:
    def __init__(self, size: int):
        self.tree = [0] * (size + 1)

    def add(self, idx: int, delta: int = 1):
        while idx < len(self.tree):
            self.tree[idx] += delta
            idx += idx & (-idx)

    def query(self, idx: int) -> int:
        s = 0
        while idx > 0:
            s += self.tree[idx]
            idx -= idx & (-idx)
        return s

class Solution:
    def countMajoritySubarrays(self, nums: list[int], target: int) -> int:
        # Transform: target -> +1, others -> -1
        # Prefix sum P[j] - P[i] > 0 <=> P[j] > P[i] for i < j
        # P values range from -N to +N. Shift by N + 1 for Fenwick index.
        n = len(nums)
        shift = n + 1
        bit = Fenwick(2 * n + 2)
        bit.add(0 + shift, 1) # P[0] = 0
        pref = 0
        ans = 0
        for x in nums:
            pref += 1 if x == target else -1
            # We want count of previous P[i] < pref <=> query((pref - 1) + shift)
            ans += bit.query((pref - 1) + shift)
            bit.add(pref + shift, 1)
        return ans

#include <vector>
using namespace std;

class Fenwick {
    vector<int> tree;
public:
    Fenwick(int n) : tree(n + 1, 0) {}
    void add(int idx, int delta = 1) {
        for (; idx < (int)tree.size(); idx += idx & (-idx)) {
            tree[idx] += delta;
        }
    }
    int query(int idx) {
        int s = 0;
        for (; idx > 0; idx -= idx & (-idx)) {
            s += tree[idx];
        }
        return s;
    }
};

class Solution {
public:
    long long countMajoritySubarrays(vector<int>& nums, int target) {
        int n = nums.size();
        int shift = n + 1;
        Fenwick bit(2 * n + 2);
        bit.add(0 + shift, 1);
        int pref = 0;
        long long ans = 0;
        for (int x : nums) {
            pref += (x == target) ? 1 : -1;
            ans += bit.query((pref - 1) + shift);
            bit.add(pref + shift, 1);
        }
        return ans;
    }
};

