        int[] tree;
        Fenwick(int n) { tree = new int[n + 1]; }
        void add(int idx, int delta) {
            for (; idx < tree.length; idx += idx & (-idx)) {
                tree[idx] += delta;
            }
        }
        int query(int idx) {
            int s = 0;
            for (; idx > 0; idx -= idx & (-idx)) {
                s += tree[idx];
            }
            return s;
        }
    }

