}

var countMajoritySubarrays = function(nums, target) {
    const n = nums.length;
    const size = 2 * n + 2;
    const tree = new Int32Array(size + 1);
    function add(idx, delta) {
        for (; idx <= size; idx += idx & (-idx)) {
            tree[idx] += delta;
        }
    }
    function query(idx) {
        let s = 0;
        for (; idx > 0; idx -= idx & (-idx)) {
            s += tree[idx];
        }
        return s;
    }
    const shift = n + 1;
    add(0 + shift, 1);
    let pref = 0;
    let ans = 0;
    for (const x of nums) {
        pref += (x === target) ? 1 : -1;
        ans += query((pref - 1) + shift);
        add(pref + shift, 1);
    }
    return ans;
};
